import{_ as d,o as e,c as o,a2 as r}from"./chunks/framework.Bg-Zxr5O.js";const A=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/CTABLES-Totals-and-Subtotals.md","filePath":"manual-zh/CTABLES-Totals-and-Subtotals.md","lastUpdated":1785684581000}'),a={name:"manual-zh/CTABLES-Totals-and-Subtotals.md"};function n(T,t,c,l,i,h){return e(),o("div",null,[...t[0]||(t[0]=[r(`<h4 id="_15-7-5-3-合计与小计" tabindex="-1">15.7.5.3 合计与小计 <a class="header-anchor" href="#_15-7-5-3-合计与小计" aria-label="Permalink to &quot;15.7.5.3 合计与小计&quot;">​</a></h4><p><code>CATEGORIES</code> 还控制合计与小计的显示。默认情况下，或使用 <code>TOTAL=NO</code> 时，不显示合计。使用 <code>TOTAL=YES</code> 可显示合计。默认合计标签为“Total”；使用 <code>LABEL=&quot;_label_ &quot;</code> 可覆盖它。</p><p>小计默认也不显示。要添加一个或多个小计，需使用显式类别列表，并在小计应出现的位置插入 <code>SUBTOTAL</code> 或 <code>HSUBTOTAL</code>。小计会成为额外的一行、一列或一个层。<code>HSUBTOTAL</code> 还会额外隐藏构成该小计的各个类别。无论哪种方式，默认标签均为“Subtotal”，可使用 <code>SUBTOTAL=&quot;_label_ &quot;</code> 或 <code>HSUBTOTAL=&quot;_label_ &quot;</code> 指定自定义标签。</p><p>下面的示例语法与输出展示了如何使用 <code>TOTAL=YES</code> 和 <code>SUBTOTAL</code>：</p><pre><code>CTABLES
    /TABLE freqOfDriving
    /CATEGORIES VARIABLES=freqOfDriving [OTHERNM, SUBTOTAL=&#39;Valid Total&#39;,
                                         MISSING, SUBTOTAL=&#39;Missing Total&#39;]
                                        TOTAL=YES LABEL=&#39;Overall Total&#39;.
</code></pre><table tabindex="0"><thead><tr><th></th><th></th><th>Count</th></tr></thead><tbody><tr><td>1. How often do you usually drive a car or other motor vehicle?</td><td>Every day</td><td>4667</td></tr><tr><td>Several days a week</td><td>1274</td><td></td></tr><tr><td>Once a week or less</td><td>361</td><td></td></tr><tr><td>Only certain times a year</td><td>130</td><td></td></tr><tr><td>Never</td><td>540</td><td></td></tr><tr><td>Valid Total</td><td>6972</td><td></td></tr><tr><td>Don&#39;t know</td><td>8</td><td></td></tr><tr><td>Refused</td><td>19</td><td></td></tr><tr><td>Missing Total</td><td>27</td><td></td></tr><tr><td>Overall Total</td><td>6999</td><td></td></tr></tbody></table><p>默认情况下，或使用 <code>POSITION=AFTER</code> 时，合计显示在最后一个类别之后，小计应用于其前面的类别。使用 <code>POSITION=BEFORE</code> 时，合计显示在第一个类别之前，小计应用于其后面的类别。</p><p>只有分类变量才能有合计与小计。标度变量可通过对其中汇总该标度变量的分类变量启用合计与小计来间接“合计”。例如，下面这段语法通过对分类变量 <code>region</code> 添加合计，得出所有数据的均值、计数和有效计数，如下所示：</p><pre><code>CTABLES /TABLE=region &gt; monthDaysMin1drink [MEAN, VALIDN]
    /CATEGORIES VARIABLES=region TOTAL=YES LABEL=&#39;All regions&#39;.
</code></pre><table tabindex="0"><thead><tr><th></th><th></th><th></th><th>Mean</th><th>Count</th><th>Valid N</th></tr></thead><tbody><tr><td>20. On how many of the thirty days in this typical month did you have one or more alcoholic beverages to drink?</td><td>Region</td><td>NE</td><td>5.6</td><td>1409</td><td>945</td></tr><tr><td>MW</td><td>5.0</td><td>1654</td><td>1026</td><td></td><td></td></tr><tr><td>S</td><td>6.0</td><td>2390</td><td>1285</td><td></td><td></td></tr><tr><td>W</td><td>6.5</td><td>1546</td><td>953</td><td></td><td></td></tr><tr><td>All regions</td><td>5.8</td><td>6999</td><td>4209</td><td></td><td></td></tr></tbody></table><p>默认情况下，PSPP 对合计与小计使用与其他类别相同的汇总函数。若要以不同方式汇总合计与小计，可在 <code>TOTALS</code> 之后的嵌套 <code>[]</code> 集合内、普通汇总函数之后指定合计与小计的汇总函数。例如，下面这段语法对各个类别显示 <code>COUNT</code>，并对合计显示 <code>COUNT</code> 与 <code>VALIDN</code>，如下所示：</p><pre><code>CTABLES
    /TABLE isLicensedDriver [COUNT, TOTALS[COUNT, VALIDN]]
    /CATEGORIES VARIABLES=isLicensedDriver TOTAL=YES MISSING=INCLUDE.
</code></pre><table tabindex="0"><thead><tr><th></th><th></th><th>Count</th><th>Valid N</th></tr></thead><tbody><tr><td>D7a. Are you a licensed driver; that is, do you have a valid driver&#39;s license?</td><td>Yes</td><td>6379</td><td></td></tr><tr><td>No</td><td>572</td><td></td><td></td></tr><tr><td>Don&#39;t know</td><td>4</td><td></td><td></td></tr><tr><td>Refused</td><td>44</td><td></td><td></td></tr><tr><td>Total</td><td>6999</td><td>6951</td><td></td></tr></tbody></table>`,13)])])}const S=d(a,[["render",n]]);export{A as __pageData,S as default};
